import { functionalUpdate, memo } from '@tanstack/react-table';
import { type RefCallback } from 'react';

import {
  type Cell,
  type Column,
  type Header,
  type InitialTableState,
  type Row,
  type RowData,
  type Table,
  type TableFeature,
  type Updater,
} from '../hooks/useTable/types.js';

/**
 * @public
 * Defines the shape of the `DataTableV2LayoutMeasuredColumnSizeState` state within the tanstack tables state.
 */
export type DataTableV2LayoutColumnMeasureInfoState = Record<
  string,
  { width: number; height: number }
>;

/**
 * @internal
 * Extension interface to extend the tanstack table state with the LineWrap state.
 */
export interface DataTableV2LayoutTableState {
  columnMeasureInfo: DataTableV2LayoutColumnMeasureInfoState;
}

/**
 * @internal
 * Extension interface to extend the types of the `Column` from the tanstack table.
 */
export interface DataTableV2LayoutColumn {
  getGridColumnPosition: () => {
    gridColumnStart: number | `span ${number}`;
    gridColumnEnd: number | `span ${number}`;
  };
}

/**
 * @internal
 * Extension interface to extend the types of the `HeaderCell` from the tanstack table.
 */
export interface DataTableV2LayoutHeader {
  getGridPosition: (columnIndex: number) => {
    gridColumnStart: number;
    gridColumnEnd: number | `span ${number}`;
    gridRowStart: number;
    gridRowEnd: number | `span ${number}`;
  };

  // Gets the measureRef that can be bound onto a cell
  // in order to get an automatic content width.
  getMeasureRef: () => RefCallback<HTMLElement> | undefined;
}

/**
 * @internal
 * Extension interface to exnted the types of the `Cell` from the tanstack table.
 */
export interface DataTableV2LayoutCell {
  getGridPosition: (columnIndex: number) => {
    gridColumnStart: number;
    gridColumnEnd: number;
    gridRowStart: number;
    gridRowEnd: number;
  };
}

/**
 * @internal
 * Extension interface to extend the types of the columnDefinition from the tanstack table.
 */
export interface DataTableV2LayoutColumnDef {
  minWidth?: number;

  /**
   * Defines the preferred width of a column.
   * Options number | `${number}fr` | 'auto' | 'content'
   * - number: Defines the width of a column in pixels
   * - `${number}fr`: Lets you define a fractioned width. Child columns with fractions can split their fractions between the parents fraction.
   * - auto: Will distribute the space evenly between the auto columns. Leverages the auto sizing feature of a CSS grid
   * - content: Will look at content visible in the first render and size the columns according to their max-content.
   */
  width?: number | `${number}fr` | 'auto' | 'content';

  maxWidth?: number;
}

/**
 * @internal
 * Extension interface to extend the types from the tanstack table instance.
 */
export interface DataTableV2LayoutInstance {
  getTableGridTemplate: () => string;

  _columnMeasureStack: Array<{
    columnId: string;
    width: number;
    height: number;
  }>;

  setColumnMeasureInfo: (
    update: Updater<DataTableV2LayoutColumnMeasureInfoState>,
  ) => void;
}

/**
 * @internal
 * Typeguard function to make sure a passed width is a fraction width.
 */
function isFractionWidth(
  width?: number | `${number}fr` | 'auto' | 'content',
): width is `${number}fr` {
  return typeof width === 'string' && width.endsWith('fr');
}

export const Layout: TableFeature = {
  getInitialState(state?: InitialTableState) {
    return {
      columnMeasureInfo: {},
      ...state,
    };
  },

  createHeader<TData extends RowData, TValue>(
    header: Header<TData, TValue>,
    table: Table<TData>,
  ) {
    header.getGridPosition = (columnIndex: number) => {
      // Get the start of the column index the header should be rendered into,
      // this should be equal to the index of the header cell in the loop passed
      // to this function.
      const gridColumnStart = columnIndex;

      // The header already exposes a colSpan value, which can be used to span
      // the header cell element from the start position to the end of the
      // header group.
      const gridColumnEnd = `span ${header.colSpan}` as `span ${number}`;

      // Get the start of the index as this is actually the defined
      // column nesting level. If the column is not nested, it will get a
      // depth of 0, and nesting levels increase going deeper.
      const gridRowStart = header.column.depth;

      // Get the end from the headers depth, as this is where it would be rendered
      // within the tanstack table. As nested columns would be rendered in the
      // lower headerrow. The strato approach here is different, as the header
      // cell should span both header rows
      const gridRowEnd = header.depth;

      // return the gridColumn positioning. As the grid column positioning in
      // css is One-based, it needs an offset of 1 in every entry.
      return {
        gridColumnStart: gridColumnStart + 1,
        gridColumnEnd,
        gridRowStart: gridRowStart + 1,
        gridRowEnd: `span ${gridRowEnd - gridRowStart}`,
      };
    };

    header.getMeasureRef = memo(
      // The dependency should align with the check on how many columns the measurement
      // should happen.
      () => [table.getAllFlatColumns()],
      () => {
        // Early exit if the columnDefintion configurations width
        // does not match the accepted widths for cachable widths.
        if (
          table.getState().columnMeasureInfo[header.column.id] !== undefined &&
          header.column.columnDef.width !== 'auto' &&
          header.column.columnDef.width !== 'content'
        ) {
          return;
        }

        return (element: HTMLElement) => {
          // Early exit as in the first render, the reference is not defined.
          if (!element) {
            return;
          }
          // This needs to be delayed, because when not delaying it
          // the header is the first element that is rendered in the grids, which does
          // not expand the grid template as wide as the bodies contents would push it.
          // It would only measure the header cells width, which is not helpful.
          table._queue(() => {
            // Get the size of the rendered element from the DOM.
            const { width, height } = element.getBoundingClientRect();
            // Push to a mutable stack during the first render. Only when the stack
            // reaches the size of the currently rendered header cells, the tables state is
            // updated and the layout updates.
            table._columnMeasureStack.push({
              columnId: header.column.id,
              width,
              height,
            });

            // Wait until all header cells have been measured before updating the
            // measure state in the table instance.
            if (
              table._columnMeasureStack.length >=
              table.getAllFlatColumns().length
            ) {
              const measure = table._columnMeasureStack.reduce(
                (measures, measure) => {
                  measures[measure.columnId] = {
                    width: measure.width,
                    height: measure.height,
                  };
                  return measures;
                },
                {},
              );

              table.setColumnMeasureInfo((previous) => ({
                ...previous,
                ...measure,
              }));
              table._columnMeasureStack = [];
            }
          });
        };
      },
      {
        key: 'header-measure',
      },
    );
  },

  createCell<TData extends RowData, TValue>(
    cell: Cell<TData, TValue>,
    column: Column<TData, TValue>,
    row: Row<TData>,
    table: Table<TData>,
  ) {
    cell.getGridPosition = (columnIndex: number) => {
      const headerGroupsLength = table.getHeaderGroups().length;

      // Initialize the pageRowOffset and correct for manual / automatic pagination
      // in the grid template.
      let pageRowOffset = 0;
      if (
        table.options.enablePagination === true &&
        table.options.manualPagination === false
      ) {
        const paginationState = table.getState().pagination;
        pageRowOffset = paginationState.pageSize * paginationState.pageIndex;
      }

      return {
        // Offset the index by one as the CSS grid column is a one based position.
        gridColumnStart: columnIndex + 1,
        // Offset the index by one as the CSS grid column is a one based position.
        gridColumnEnd: columnIndex + 1,
        // Offset the row index by the number of displayed headers, as headers and rows
        // live within the same grid.
        // Also offset them by one as the CSS grid row is a one based position.
        gridRowStart: headerGroupsLength - pageRowOffset + row.index + 1,
        // Offset the row index by the number of displayed headers, as headers and rows
        // live within the same grid.
        // Also offset them by one as the CSS grid row is a one based position.
        gridRowEnd: headerGroupsLength - pageRowOffset + row.index + 1,
      };
    };
  },

  createTable<TData extends RowData>(table: Table<TData>): void {
    // Declares a cache layer for the measurements of the header cells
    table._columnMeasureStack = table._columnMeasureStack ?? [];

    table.setColumnMeasureInfo = (updater) => {
      table.setState((previous) => ({
        ...previous,
        columnMeasureInfo: functionalUpdate(
          updater,
          previous.columnMeasureInfo,
        ),
      }));
    };

    table.getTableGridTemplate = memo(
      () => [table.getAllLeafColumns(), table.getState().columnMeasureInfo],
      () => {
        const allColumns = table.getAllLeafColumns();

        // Here we want to deal first with initial sizing
        // So we create a grid layout, that is used as a default

        // But then read what the resizer considers as an update
        // this way, we would also be able to _reset_ to the original
        // size, if we want it to.
        const columnsTemplate: string[] = [];

        for (const column of allColumns) {
          const {
            minWidth = 30,
            width,
            maxWidth = Number.MAX_SAFE_INTEGER,
          } = column.columnDef;

          // Fallback if the width is not defined, we define a layout fallback
          if (width === undefined) {
            columnsTemplate.push('1fr');
            continue;
          }

          // If the width is a number, we can assume this is a pixel value that it
          // wants to adjust for.
          if (typeof width === 'number') {
            columnsTemplate.push(`${width}px`);
            continue;
          }

          if (typeof width === 'string') {
            // If the width definition is a fraction, we can use it as a
            // fraction layout value
            if (isFractionWidth(width)) {
              // If there is a parent column and it also has a fraction width
              // defined, we can calculate more accurate fractions for the
              // children columns based on the relationship between parent columns
              // fraction size and the current child columns size.
              if (
                column.parent &&
                isFractionWidth(column.parent.columnDef.width)
              ) {
                const parentFraction = parseFloat(
                  column.parent.columnDef.width,
                );
                const columnFraction = parseFloat(
                  column.columnDef.width as `${number}fr`,
                );

                const siblingColumns = column.parent.getLeafColumns();
                const siblingColumnsSum = siblingColumns.reduce(
                  (sum, column) => {
                    if (isFractionWidth(column.columnDef.width)) {
                      return sum + parseFloat(column.columnDef.width);
                    }
                    return sum;
                  },
                  0,
                );

                const calculatedFraction =
                  parentFraction * (columnFraction / siblingColumnsSum);

                columnsTemplate.push(
                  // DISCUSS: Putting the fraction here might not be ideal here,
                  // as it does not clamp max-widths. But the current implementation
                  // of the DataTable layout also does not take this into account.
                  `${calculatedFraction}fr`,
                );

                continue;
              } else {
                columnsTemplate.push(width);
                continue;
              }
            }

            // Set the width to `auto` and let the grid layout span the value
            if (width === 'auto') {
              const measurement = table.getState().columnMeasureInfo[column.id];
              let columnTemplateValue = 'auto';
              if (
                measurement !== undefined &&
                measurement.width !== undefined
              ) {
                columnTemplateValue = `${Math.max(
                  minWidth,
                  Math.min(measurement.width, maxWidth),
                )}px`;
              }

              columnsTemplate.push(columnTemplateValue);
              continue;
            }

            // Set the width to `content` and let the grid layout span the value
            if (width === 'content') {
              const measurement = table.getState().columnMeasureInfo[column.id];
              let columnTemplateValue = 'max-content';
              if (
                measurement !== undefined &&
                measurement.width !== undefined
              ) {
                columnTemplateValue = `${Math.max(
                  minWidth,
                  Math.min(measurement.width, maxWidth),
                )}px`;
              }

              columnsTemplate.push(columnTemplateValue);
              continue;
            }
          }
        }

        return columnsTemplate.join(' ');
      },
      { key: process.env.NODE_ENV === 'development' && 'getTableGridTemplate' },
    );
  },
};
